// <diletta-spot-icon> — a INSTÂNCIA WEB de `design-system-spot-icon`.
//
// 114 usos no BackOffice, e é ela que faz o medalhão ao lado do título de página.
// Ficou fora da tradução até 07/09/2026 por dois motivos, e o segundo era um anel
// que ninguém enxergava.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-spot-icon';
const TYPE = ['fill', 'outline'];
const STATE = ['normal', 'disabled', 'primary', 'error', 'warning', 'success', 'secure', 'loading'];

// O tamanho é livre e o glifo é uma PROPORÇÃO dele: 58%, arredondado. Está no Dart
// como `(size * 0.58).roundToDouble()`, e o default é 34.
const PADRAO = 34;
const RAZAO = 0.58;
const FORMA = ['circulo', 'ladrilho'];
// O raio do ladrilho segue a ESCALA e não o sítio: 8 abaixo de 44, 16 a partir
// dele. Medido em seis ladrilhos de 36 a 48, que usavam três raios diferentes.
const raioDoLadrilho = (tamanho) => (tamanho < 44 ? 8 : 16);

class DilettaSpotIcon extends HTMLElement {
  static observedAttributes = ['type', 'state', 'forma', 'size', 'rotulo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  render() {
    const type = eixo(this, 'type', TYPE, 'fill');
    const state = eixo(this, 'state', STATE, 'normal');
    const size = Number(this.getAttribute('size')) || PADRAO;
    const forma = eixo(this, 'forma', FORMA, 'circulo');
    const p = papeisDe(SLUG, { Type: type, State: state });
    const rotulo = this.getAttribute('rotulo');

    // Sem rótulo ele é DECORAÇÃO e sai da árvore: um medalhão ao lado de um título
    // que já diz a mesma coisa seria lido duas vezes. Com rótulo, vira imagem
    // nomeada. Quem decide é quem chama, porque só ela sabe se há texto ao lado.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-flex; }
        .spot {
          box-sizing: border-box;
          width: ${size}px; height: ${size}px;
          border-radius: ${forma === 'circulo' ? '999px' : raioDoLadrilho(size) + 'px'};
          display: inline-flex; align-items: center; justify-content: center;
          border-width: 1px; border-style: solid; border-color: transparent;
          ${estiloDa(p)}
        }
        ::slotted(svg) { width: ${Math.round(size * RAZAO)}px;
                         height: ${Math.round(size * RAZAO)}px; }
      </style>
      <span class="spot" part="spot"
        ${rotulo ? `role="img" aria-label="${rotulo.replace(/"/g, '&quot;')}"`
                 : 'aria-hidden="true"'}><slot></slot></span>`;
  }
}

customElements.define('diletta-spot-icon', DilettaSpotIcon);
export { DilettaSpotIcon, PADRAO, RAZAO };
